/**
 * Staff only. Same model as ../facts-directory-search: an AdminDirectory OU check with a manual
 * ALLOWED_EMAILS Script Property as override and fallback. This board carries student PII, so it
 * must never be exposed as "anyone with the link".
 *
 * NOTE the OU is named "Staff & Teachers", NOT "Teachers & Staff".
 */
var PROP_ALLOWED_OU = 'ALLOWED_OU_PREFIX';
var DEFAULT_ALLOWED_OU = '/Staff & Teachers'; // real OU name, verified in facts-directory-search
var PROP_ALLOWED_EMAILS = 'ALLOWED_EMAILS';
var ALLOW_CACHE_SECONDS = 21600;   // positives cached 6h; denials always re-checked live

/** Allowed OU prefix, trailing slash stripped and LOWERCASED for comparison. */
function getAllowedOuPrefix_() {
  var raw = PropertiesService.getScriptProperties().getProperty(PROP_ALLOWED_OU) || DEFAULT_ALLOWED_OU;
  return raw.replace(/\/+$/, '').toLowerCase();
}

/** Manual allowlist — the bootstrap and the fallback when the directory is unreachable. */
function getAllowlist_() {
  var raw = PropertiesService.getScriptProperties().getProperty(PROP_ALLOWED_EMAILS) || '';
  return raw.split(/[,\s]+/).map(function (e) { return e.trim().toLowerCase(); })
    .filter(function (e) { return e; });
}

/**
 * OU membership. Mirrors ../facts-directory-search/Config.gs isInAllowedOu_ (copied 2026-09-03) —
 * two details there are load-bearing and were missing from the first version of this file:
 *   - compare LOWERCASED on both sides, and anchor on prefix + '/', so "/Staff & Teachers Archive"
 *     cannot match the "/Staff & Teachers" prefix
 *   - reject SUSPENDED accounts, which still resolve and still carry their old OU
 * @return {{ok: boolean, why: string}} why is for diagnostics only — never shown to a denied user.
 */
function ouDecision_(email) {
  var cache = CacheService.getScriptCache();
  var key = 'ou_ok_' + email;
  if (cache.get(key) === '1') return { ok: true, why: 'cached' };
  try {
    var u = AdminDirectory.Users.get(email, { fields: 'orgUnitPath,suspended' });
    var ou = String((u && u.orgUnitPath) || '');
    if (u && u.suspended) return { ok: false, why: 'account suspended (OU ' + ou + ')' };
    var ok = (ou.toLowerCase() + '/').indexOf(getAllowedOuPrefix_() + '/') === 0;
    if (ok) cache.put(key, '1', ALLOW_CACHE_SECONDS);
    return { ok: ok, why: ok ? 'OU ' + ou : 'OU "' + ou + '" is outside "' + getAllowedOuPrefix_() + '"' };
  } catch (e) {
    // NOT the same as "not staff": could be an unauthorized AdminDirectory scope, the advanced
    // service not enabled, or a caller without directory-read rights. The first version of this
    // file swallowed this and returned a bare "Not authorized.", which is indistinguishable from a
    // real denial and cost a debugging round trip. Carry the reason for the diagnostics below.
    return { ok: false, why: 'directory lookup FAILED: ' + String(e).slice(0, 160) };
  }
}

function isAllowed_(email) {
  var e = String(email || '').trim().toLowerCase();
  if (!e) return false;
  if (getAllowlist_().indexOf(e) !== -1) return true;
  return ouDecision_(e).ok;
}

/** Throw unless the caller is staff. EVERY server entry point calls this, not just doGet. */
function requireStaff_() {
  var email = (Session.getActiveUser().getEmail() || '').toLowerCase();
  if (!isAllowed_(email)) {
    throw new Error('Not authorized (' + (email || 'no signed-in user') +
      '). Run RUN_whoAmI in Config.gs to see exactly why.');
  }
  return email;
}

/**
 * Throw unless this is running from the SCRIPT EDITOR (or as the deploying account itself).
 *
 * google.script.run reaches every global function — including from the "Not authorized" page,
 * which is still an HtmlService page with the client library loaded. So a RUN_ function that
 * GRANTS access or seeds an Admin must not be reachable by a web visitor at all: any domain
 * account, a student included, could otherwise open the denied page's console and add themselves.
 * In the web app the active user is the VISITOR and the effective user is the DEPLOYER (executeAs
 * USER_DEPLOYING); in the editor they are the same person. That difference is the gate.
 */
function requireEditor_() {
  var active = (Session.getActiveUser().getEmail() || '').toLowerCase();
  var effective = (Session.getEffectiveUser().getEmail() || '').toLowerCase();
  if (!active || active !== effective) {
    throw new Error('This function can only be run from the script editor.');
  }
  return active;
}

/**
 * WHY am I allowed or denied? In Config.gs, run from the editor Run menu.
 * Prints the decision and its reason without changing anything.
 */
function RUN_whoAmI() {
  // EDITOR ONLY. google.script.run reaches ANY global in this project regardless of what the
  // page renders, and doGet serves an HtmlService page even to somebody it has just refused —
  // so a denied page still carries the bridge. requireEditor_ compares the ACTIVE user to the
  // EFFECTIVE one: equal only in the editor, never through the deployed web app, and never
  // under a trigger. Added by the 2026-09-18 audit, which found 14 of these ungated, six of
  // them writers and four of those one clearContents() from an empty tab.
  requireEditor_();
  var email = (Session.getActiveUser().getEmail() || '').toLowerCase();
  Logger.log('signed in as      : %s', email || '(none — the editor could not resolve a user)');
  Logger.log('manual allowlist  : %s', JSON.stringify(getAllowlist_()));
  Logger.log('allowed OU prefix : "%s"', getAllowedOuPrefix_());
  if (getAllowlist_().indexOf(email) !== -1) {
    Logger.log('DECISION          : ALLOWED (manual allowlist)');
    return;
  }
  var d = ouDecision_(email);
  Logger.log('OU check          : %s — %s', d.ok ? 'pass' : 'FAIL', d.why);
  Logger.log('DECISION          : %s', d.ok ? 'ALLOWED' : 'DENIED');
  if (!d.ok && /FAILED/.test(d.why)) {
    Logger.log('  A directory FAILURE is not the same as "not staff". Either the AdminDirectory');
    Logger.log('  advanced service needs authorizing (re-run and accept the prompt), or this');
    Logger.log('  account cannot read the directory. RUN_grantMyself unblocks you either way.');
  }
}

/**
 * Bootstrap: add the current user to ALLOWED_EMAILS so the app is usable while the directory
 * check is sorted out. In Config.gs, run from the editor Run menu. Additive — it never removes
 * anyone, and the OU check keeps working for everybody else.
 */
function RUN_grantMyself() {
  requireEditor_();          // grants ACCESS to the caller — never reachable from a web visitor
  var email = (Session.getActiveUser().getEmail() || '').toLowerCase();
  if (!email) throw new Error('Could not resolve a signed-in user.');
  var list = getAllowlist_();
  if (list.indexOf(email) !== -1) {
    Logger.log('%s is already on the allowlist: %s', email, JSON.stringify(list));
    return list;
  }
  list.push(email);
  PropertiesService.getScriptProperties().setProperty(PROP_ALLOWED_EMAILS, list.join(','));
  Logger.log('Added %s. Allowlist is now: %s', email, JSON.stringify(list));
  return list;
}

